param([string]$BuildDir = "build")
$ErrorActionPreference = "Stop"
$projectRoot = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot ".."))
$targetPath = [IO.Path]::GetFullPath((Join-Path $projectRoot $BuildDir))
$allowedPrefix = $projectRoot.TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
if (-not $targetPath.StartsWith($allowedPrefix, [StringComparison]::OrdinalIgnoreCase)) {
    throw "Refusing to clean outside the project: $targetPath"
}
# Delete only the flat build artifacts generated by this Makefile, without recursion.
if (Test-Path -LiteralPath $targetPath) {
    Get-ChildItem -LiteralPath $targetPath -File |
        Where-Object { $_.Extension -in '.o', '.d', '.elf', '.hex', '.bin', '.map' } |
        ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force }
}
